class Solution:
    def solve(self, spec_path: str = None) -> dict:
        code = r'''
import networkx as nx
from collections import defaultdict
import random
import math

class BroadCastTopology:
    def __init__(self, src: str, dsts: list, num_partitions: int):
        self.src = src
        self.dsts = dsts
        self.num_partitions = int(num_partitions)
        self.paths = {dst: {str(i): None for i in range(self.num_partitions)} for dst in dsts}

    def append_dst_partition_path(self, dst: str, partition: int, path: list):
        partition = str(partition)
        if self.paths[dst][partition] is None:
            self.paths[dst][partition] = []
        self.paths[dst][partition].append(path)

    def set_dst_partition_paths(self, dst: str, partition: int, paths: list):
        partition = str(partition)
        self.paths[dst][partition] = paths

    def set_num_partitions(self, num_partitions: int):
        self.num_partitions = num_partitions


def search_algorithm(src, dsts, G, num_partitions):
    bc_topology = BroadCastTopology(src, dsts, num_partitions)

    num_vms = 2
    instance_rate = 0.54

    ingress_limit_map = {"aws": 10, "gcp": 16, "azure": 16}
    egress_limit_map = {"aws": 5, "gcp": 7, "azure": 16}

    if hasattr(G, 'graph'):
        if 'num_vms' in G.graph:
            num_vms = int(G.graph['num_vms'])

    data_vol_gb = 1.0
    if hasattr(G, 'graph') and 'data_vol' in G.graph:
        data_vol_gb = float(G.graph['data_vol'])

    partition_size_gb = data_vol_gb / num_partitions

    def get_provider(node):
        parts = node.split(":")
        if len(parts) >= 1:
            p = parts[0]
            if p in ("aws", "gcp", "azure"):
                return p
        return "aws"

    def get_node_egress_gbps(node):
        provider = get_provider(node)
        return egress_limit_map.get(provider, 5) * num_vms

    def get_node_ingress_gbps(node):
        provider = get_provider(node)
        return ingress_limit_map.get(provider, 10) * num_vms

    def path_edges_list(path):
        edges = []
        for i in range(len(path) - 1):
            u, v = path[i], path[i+1]
            if G.has_edge(u, v):
                edges.append([u, v, dict(G[u][v])])
            else:
                edges.append([u, v, {}])
        return edges

    # Compute cost: egress cost + instance cost
    # The key insight: total_time is determined by the bottleneck
    # Each edge carries some number of partition-flows
    # Each node has egress/ingress limits shared across all its edges
    def compute_cost_from_paths(dst_paths):
        """dst_paths: dict {dst: {partition_int: node_list_path}}"""
        # Count flows per edge and track node edge usage
        edge_flow_count = defaultdict(int)  # (u,v) -> num partition-flows
        node_out_edges = defaultdict(set)   # node -> set of (u,v) edges used for output
        node_in_edges = defaultdict(set)    # node -> set of (u,v) edges used for input
        nodes_used = set()

        for dst in dsts:
            for p in range(num_partitions):
                path = dst_paths.get(dst, {}).get(p)
                if path is None:
                    continue
                for i in range(len(path) - 1):
                    u, v = path[i], path[i+1]
                    edge_flow_count[(u, v)] += 1
                    node_out_edges[u].add((u, v))
                    node_in_edges[v].add((u, v))
                    nodes_used.add(u)
                    nodes_used.add(v)

        if not edge_flow_count:
            return float('inf')

        # Egress cost
        egress_cost = 0.0
        for (u, v), count in edge_flow_count.items():
            c = 0.0
            if G.has_edge(u, v):
                c = G[u][v].get("cost", 0.0)
            egress_cost += count * partition_size_gb * c

        # Time calculation: 
        # Each edge has throughput limit
        # Each node's egress bandwidth is shared among outgoing edges
        # Each node's ingress bandwidth is shared among incoming edges
        # The effective bandwidth of edge (u,v) = min(throughput, egress_share, ingress_share)
        # Time for edge = data_on_edge / effective_bw
        # Total time = max over all edges

        # Compute per-node bandwidth allocation
        # Simple model: equal share among edges
        max_time = 0.0

        for (u, v), count in edge_flow_count.items():
            tp = 1.0
            if G.has_edge(u, v):
                tp = G[u][v].get("throughput", 1.0)

            n_out = len(node_out_edges[u])
            n_in = len(node_in_edges[v])

            eg = get_node_egress_gbps(u) / max(n_out, 1)
            ig = get_node_ingress_gbps(v) / max(n_in, 1)

            bw = min(tp, eg, ig)
            if bw <= 0:
                bw = 0.001

            data_gb = count * partition_size_gb
            t = data_gb * 8.0 / bw  # time in seconds
            if t > max_time:
                max_time = t

        inst_cost = len(nodes_used) * num_vms * (instance_rate / 3600.0) * max_time

        return egress_cost + inst_cost

    # Alternative cost: consider that flows through same edge are sequential
    # or that bandwidth is shared per-flow on each edge
    def compute_cost_v2(dst_paths):
        """More refined: each edge's bandwidth is shared among flows on it"""
        edge_flow_count = defaultdict(int)
        node_out_edges = defaultdict(set)
        node_in_edges = defaultdict(set)
        nodes_used = set()

        for dst in dsts:
            for p in range(num_partitions):
                path = dst_paths.get(dst, {}).get(p)
                if path is None:
                    continue
                for i in range(len(path) - 1):
                    u, v = path[i], path[i+1]
                    edge_flow_count[(u, v)] += 1
                    node_out_edges[u].add((u, v))
                    node_in_edges[v].add((u, v))
                    nodes_used.add(u)
                    nodes_used.add(v)

        if not edge_flow_count:
            return float('inf')

        egress_cost = 0.0
        for (u, v), count in edge_flow_count.items():
            c = 0.0
            if G.has_edge(u, v):
                c = G[u][v].get("cost", 0.0)
            egress_cost += count * partition_size_gb * c

        # For time: consider node bandwidth constraints
        # Total data out of node u = sum over edges (u,v) of flow_count * partition_size
        # Time at node u for egress = total_data_out * 8 / egress_gbps
        # Similarly for ingress
        # Also per-edge: data / throughput

        max_time = 0.0

        # Node egress bottleneck
        for u, edges in node_out_edges.items():
            total_data = sum(edge_flow_count[e] * partition_size_gb for e in edges)
            eg_bw = get_node_egress_gbps(u)
            if eg_bw <= 0:
                eg_bw = 0.001
            t = total_data * 8.0 / eg_bw
            if t > max_time:
                max_time = t

        # Node ingress bottleneck
        for v, edges in node_in_edges.items():
            total_data = sum(edge_flow_count[e] * partition_size_gb for e in edges)
            ig_bw = get_node_ingress_gbps(v)
            if ig_bw <= 0:
                ig_bw = 0.001
            t = total_data * 8.0 / ig_bw
            if t > max_time:
                max_time = t

        # Edge throughput bottleneck
        for (u, v), count in edge_flow_count.items():
            tp = 1.0
            if G.has_edge(u, v):
                tp = G[u][v].get("throughput", 1.0)
            if tp <= 0:
                tp = 0.001
            data_gb = count * partition_size_gb
            t = data_gb * 8.0 / tp
            if t > max_time:
                max_time = t

        inst_cost = len(nodes_used) * num_vms * (instance_rate / 3600.0) * max_time

        return egress_cost + inst_cost

    # Try both cost models and use the one that gives more consistent results
    # We'll use v2 as our primary model (seems more realistic)

    def compute_cost(dst_paths):
        c1 = compute_cost_from_paths(dst_paths)
        c2 = compute_cost_v2(dst_paths)
        return max(c1, c2)  # Conservative: use worst case

    # Build candidate paths per destination
    K_PATHS = 30
    dst_candidates = {}

    for dst in dsts:
        cands = []
        seen = set()

        def add_path(p):
            key = tuple(p)
            if key not in seen:
                seen.add(key)
                cands.append(p)

        # Cost-shortest paths
        try:
            gen = nx.shortest_simple_paths(G, src, dst, weight="cost")
            for i, path in enumerate(gen):
                if i >= K_PATHS:
                    break
                add_path(path)
        except:
            pass

        # Hop-shortest path
        try:
            sp = nx.shortest_path(G, src, dst)
            add_path(sp)
        except:
            pass

        # Max-throughput path (min 1/throughput)
        try:
            tp_path = nx.dijkstra_path(G, src, dst, weight=lambda u, v, d: 1.0 / max(d.get("throughput", 0.001), 0.001))
            add_path(tp_path)
        except:
            pass

        # Weighted combo paths
        for lam in [0.0001, 0.001, 0.005, 0.01, 0.02, 0.05, 0.1, 0.2, 0.5, 1.0, 2.0, 5.0, 10.0, 50.0]:
            try:
                wp = nx.dijkstra_path(G, src, dst, weight=lambda u, v, d, l=lam: d.get("cost", 0) + l / max(d.get("throughput", 0.001), 0.001))
                add_path(wp)
            except:
                pass

        # Min nodes path (to reduce instance cost)
        try:
            wp = nx.dijkstra_path(G, src, dst, weight=lambda u, v, d: 1.0)
            add_path(wp)
        except:
            pass

        dst_candidates[dst] = cands

    def build_dst_paths(assignment):
        result = {}
        for dst in dsts:
            result[dst] = {}
            cands = dst_candidates.get(dst, [])
            for p in range(num_partitions):
                idx = assignment.get((dst, p), 0)
                if cands and idx < len(cands):
                    result[dst][p] = cands[idx]
                elif cands:
                    result[dst][p] = cands[0]
                else:
                    result[dst][p] = None
        return result

    def eval_assignment(assignment):
        return compute_cost(build_dst_paths(assignment))

    # ================================================================
    # Strategy 1: Cheapest single path per dst (by egress cost only)
    # ================================================================
    def strategy_cheapest_egress():
        assignment = {}
        for dst in dsts:
            cands = dst_candidates.get(dst, [])
            if not cands:
                continue
            best_idx = 0
            best_c = float('inf')
            for idx, path in enumerate(cands):
                c = sum(G[path[i]][path[i+1]].get("cost", 0) for i in range(len(path)-1))
                if c < best_c:
                    best_c = c
                    best_idx = idx
            for p in range(num_partitions):
                assignment[(dst, p)] = best_idx
        return assignment

    # ================================================================
    # Strategy 2: Min hops (minimize instance cost)
    # ================================================================
    def strategy_min_hops():
        assignment = {}
        for dst in dsts:
            cands = dst_candidates.get(dst, [])
            if not cands:
                continue
            best_idx = min(range(len(cands)), key=lambda i: len(cands[i]))
            for p in range(num_partitions):
                assignment[(dst, p)] = best_idx
        return assignment

    # ================================================================
    # Strategy 3: Max throughput path
    # ================================================================
    def strategy_max_tp():
        assignment = {}
        for dst in dsts:
            cands = dst_candidates.get(dst, [])
            if not cands:
                continue

            def path_min_tp(path):
                min_tp = float('inf')
                for i in range(len(path)-1):
                    tp = G[path[i]][path[i+1]].get("throughput", 0.001)
                    if tp < min_tp:
                        min_tp = tp
                return min_tp

            best_idx = max(range(len(cands)), key=lambda i: path_min_tp(cands[i]))
            for p in range(num_partitions):
                assignment[(dst, p)] = best_idx
        return assignment

    # ================================================================
    # Strategy 4: Evaluate each candidate per dst with full cost model
    # ================================================================
    def strategy_per_dst_eval():
        assignment = {}
        for dst in dsts:
            for p in range(num_partitions):
                assignment[(dst, p)] = 0

        for dst in dsts:
            cands = dst_candidates.get(dst, [])
            if not cands:
                continue

            best_idx = 0
            best_c = float('inf')

            for idx in range(len(cands)):
                for p in range(num_partitions):
                    assignment[(dst, p)] = idx
                c = eval_assignment(assignment)
                if c < best_c:
                    best_c = c
                    best_idx = idx

            for p in range(num_partitions):
                assignment[(dst, p)] = best_idx

        return assignment

    # ================================================================
    # Strategy 5: Spread partitions across paths
    # ================================================================
    def strategy_spread(n_paths):
        assignment = {}
        for dst in dsts:
            cands = dst_candidates.get(dst, [])
            if not cands:
                continue
            # Sort candidates by cost
            ranked = sorted(range(len(cands)), key=lambda i: sum(
                G[cands[i][j]][cands[i][j+1]].get("cost", 0) for j in range(len(cands[i])-1)
            ))
            n_use = min(len(ranked), n_paths)
            for p in range(num_partitions):
                assignment[(dst, p)] = ranked[p % n_use]
        return assignment

    # ================================================================
    # Strategy 6: Steiner-tree inspired (share edges)
    # ================================================================
    def strategy_steiner():
        assignment = {}
        tree_g = nx.DiGraph()
        tree_g.add_node(src)
        remaining = sorted(dsts, key=lambda d: nx.dijkstra_path_length(G, src, d, weight="cost") if nx.has_path(G, src, d) else float('inf'))

        dst_full_path = {}

        for dst in remaining:
            best_path = None
            best_cost = float('inf')

            # Try connecting from any tree node
            for tn in list(tree_g.nodes()):
                try:
                    path = nx.shortest_path(G, tn, dst, weight="cost")
                    cost = sum(G[path[i]][path[i+1]].get("cost", 0) for i in range(len(path)-1))
                    # Discount edges already in tree
                    for i in range(len(path)-1):
                        if tree_g.has_edge(path[i], path[i+1]):
                            cost -= G[path[i]][path[i+1]].get("cost", 0) * 0.8
                    if cost < best_cost:
                        best_cost = cost
                        best_path = (tn, path)
                except:
                    pass

            if best_path:
                tn, path = best_path
                for i in range(len(path)-1):
                    if not tree_g.has_edge(path[i], path[i+1]):
                        tree_g.add_edge(path[i], path[i+1], **dict(G[path[i]][path[i+1]]))

                try:
                    full_path = nx.shortest_path(tree_g, src, dst, weight="cost")
                    dst_full_path[dst] = full_path
                except:
                    cands = dst_candidates.get(dst, [])
                    if cands:
                        dst_full_path[dst] = cands[0]
            else:
                cands = dst_candidates.get(dst, [])
                if cands:
                    dst_full_path[dst] = cands[0]

        for dst in dsts:
            cands = dst_candidates.get(dst, [])
            path = dst_full_path.get(dst)
            idx = 0
            if path and cands:
                for ci, cp in enumerate(cands):
                    if cp == path:
                        idx = ci
                        break
                else:
                    # Add this path as a candidate
                    # Verify it's valid
                    valid = True
                    for i in range(len(path)-1):
                        if not G.has_edge(path[i], path[i+1]):
                            valid = False
                            break
                    if valid:
                        cands.append(path)
                        idx = len(cands) - 1
                        dst_candidates[dst] = cands

            for p in range(num_partitions):
                assignment[(dst, p)] = idx

        return assignment

    # ================================================================
    # Evaluate all strategies
    # ================================================================
    strategies = [
        ("cheapest_egress", strategy_cheapest_egress),
        ("min_hops", strategy_min_hops),
        ("max_tp", strategy_max_tp),
        ("steiner", strategy_steiner),
        ("spread2", lambda: strategy_spread(2)),
        ("spread3", lambda: strategy_spread(3)),
        ("spread5", lambda: strategy_spread(5)),
    ]

    best_assignment = None
    best_cost = float('inf')

    for name, fn in strategies:
        try:
            a = fn()
            c = eval_assignment(a)
            if c < best_cost:
                best_cost = c
                best_assignment = dict(a)
        except:
            pass

    # Per-dst evaluation (can be expensive)
    n_total_cands = sum(len(dst_candidates.get(d, [])) for d in dsts)
    if n_total_cands * len(dsts) * num_partitions < 200000:
        try:
            a = strategy_per_dst_eval()
            c = eval_assignment(a)
            if c < best_cost:
                best_cost = c
                best_assignment = dict(a)
        except:
            pass

    if best_assignment is None:
        best_assignment = {}
        for dst in dsts:
            for p in range(num_partitions):
                best_assignment[(dst, p)] = 0
        best_cost = eval_assignment(best_assignment)

    # ================================================================
    # Hill climbing: try each path for each dst
    # ================================================================
    improved = True
    hc_rounds = 0
    while improved and hc_rounds < 8:
        improved = False
        hc_rounds += 1

        for dst in dsts:
            cands = dst_candidates.get(dst, [])
            if not cands or len(cands) <= 1:
                continue

            saved = {p: best_assignment.get((dst, p), 0) for p in range(num_partitions)}

            # Try all partitions on same path
            for idx in range(len(cands)):
                for p in range(num_partitions):
                    best_assignment[(dst, p)] = idx
                c = eval_assignment(best_assignment)
                if c < best_cost - 1e-10:
                    best_cost = c
                    saved = {p: idx for p in range(num_partitions)}
                    improved = True

            # Try spreading across pairs of paths
            if len(cands) >= 2 and num_partitions >= 2:
                saved_idx = saved[0]
                for idx2 in range(len(cands)):
                    if idx2 == saved_idx:
                        continue
                    for p in range(num_partitions):
                        best_assignment[(dst, p)] = saved_idx if p % 2 == 0 else idx2
                    c = eval_assignment(best_assignment)
                    if c < best_cost - 1e-10:
                        best_cost = c
                        saved = {p: (saved_idx if p % 2 == 0 else idx2) for p in range(num_partitions)}
                        improved = True

            for p in range(num_partitions):
                best_assignment[(dst, p)] = saved[p]

    # ================================================================
    # Simulated annealing refinement
    # ================================================================
    random.seed(42)
    current = dict(best_assignment)
    current_cost = best_cost
    sa_best = dict(best_assignment)
    sa_best_cost = best_cost

    all_keys = [(dst, p) for dst in dsts for p in range(num_partitions)]
    n_items = len(all_keys)

    if n_items > 0:
        temp = max(best_cost * 0.01, 0.1)
        cooling = 0.997
        max_iters = min(15000, n_items * 50)

        for it in range(max_iters):
            key = random.choice(all_keys)
            dst, p = key
            cands = dst_candidates.get(dst, [])
            if not cands or len(cands) <= 1:
                continue

            old_idx = current.get(key, 0)

            # With some probability, swap all partitions for this dst
            if random.random() < 0.3:
                new_idx = random.randint(0, len(cands) - 1)
                if new_idx == old_idx:
                    continue
                saved_vals = {}
                for pp in range(num_partitions):
                    saved_vals[(dst, pp)] = current.get((dst, pp), 0)
                    current[(dst, pp)] = new_idx
                new_cost = eval_assignment(current)
                delta = new_cost - current_cost
                if delta < 0 or (temp > 0 and random.random() < math.exp(-delta / max(temp, 1e-10))):
                    current_cost = new_cost
                    if current_cost < sa_best_cost:
                        sa_best_cost = current_cost
                        sa_best = dict(current)
                else:
                    for k, v in saved_vals.items():
                        current[k] = v
            else:
                new_idx = random.randint(0, len(cands) - 1)
                if new_idx == old_idx:
                    continue
                current[key] = new_idx
                new_cost = eval_assignment(current)
                delta = new_cost - current_cost
                if delta < 0 or (temp > 0 and random.random() < math.exp(-delta / max(temp, 1e-10))):
                    current_cost = new_cost
                    if current_cost < sa_best_cost:
                        sa_best_cost = current_cost
                        sa_best = dict(current)
                else:
                    current[key] = old_idx

            temp *= cooling

    if sa_best_cost < best_cost:
        best_assignment = sa_best
        best_cost = sa_best_cost

    # ================================================================
    # Final hill climb
    # ================================================================
    improved = True
    hc_rounds = 0
    while improved and hc_rounds < 3:
        improved = False
        hc_rounds += 1
        for dst in dsts:
            cands = dst_candidates.get(dst, [])
            if not cands or len(cands) <= 1:
                continue
            saved = {p: best_assignment.get((dst, p), 0) for p in range(num_partitions)}
            for idx in range(len(cands)):
                for p in range(num_partitions):
                    best_assignment[(dst, p)] = idx
                c = eval_assignment(best_assignment)
                if c < best_cost - 1e-10:
                    best_cost = c
                    saved = {p: idx for p in range(num_partitions)}
                    improved = True
            for p in range(num_partitions):
                best_assignment[(dst, p)] = saved[p]

    # ================================================================
    # Build final topology
    # ================================================================
    for dst in dsts:
        cands = dst_candidates.get(dst, [])
        if not cands:
            continue
        for p in range(num_partitions):
            idx = best_assignment.get((dst, p), 0)
            if idx >= len(cands):
                idx = 0
            path = cands[idx]
            edges = path_edges_list(path)
            bc_topology.set_dst_partition_paths(dst, p, edges)

    return bc_topology
'''
        return {"code": code}
